const wasteOfDay = `-- name: WasteOfDay :many
select w.id, w.item_type, coalesce(i.name, p.name)::text as item_name, w.quantity, w.entered_qty,
       coalesce(u.code, 'pza')::text as unit_code, w.total_cost, w.status, w.note,
       r.name as reason_name, w.recorded_by, uu.name as recorded_by_name, w.recorded_at
  from waste_records w
  join waste_reasons r on r.id = w.reason_id
  join users uu on uu.id = w.recorded_by
  left join ingredients i on i.id = w.ingredient_id
  left join units u on u.id = i.base_unit_id
  left join products p on p.id = w.product_id
 where w.branch_id = current_branch_id() and w.recorded_at >= $1
 order by w.recorded_at desc, w.id desc
`

type WasteOfDayRow struct {
	ID             int64            `json:"id"`
	ItemType       StockItemType    `json:"item_type"`
	ItemName       string           `json:"item_name"`
	Quantity       decimal.Decimal  `json:"quantity"`
	EnteredQty     decimal.Decimal  `json:"entered_qty"`
	UnitCode       string           `json:"unit_code"`
	TotalCost      *decimal.Decimal `json:"total_cost"`
	Status         string           `json:"status"`
	Note           *string          `json:"note"`
	ReasonName     string           `json:"reason_name"`
	RecordedBy     int64            `json:"recorded_by"`
	RecordedByName string           `json:"recorded_by_name"`
	RecordedAt     time.Time        `json:"recorded_at"`
}

// Lo registrado en la sucursal desde un momento (el inicio del día del local).
func (q *Queries) WasteOfDay(ctx context.Context, since time.Time) ([]WasteOfDayRow, error) {
	rows, err := q.db.Query(ctx, wasteOfDay, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WasteOfDayRow{}
	for rows.Next() {
		var i WasteOfDayRow
		if err := rows.Scan(
			&i.ID,
			&i.ItemType,
			&i.ItemName,
			&i.Quantity,
			&i.EnteredQty,
			&i.UnitCode,
			&i.TotalCost,
			&i.Status,
			&i.Note,
			&i.ReasonName,
			&i.RecordedBy,
			&i.RecordedByName,
			&i.RecordedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
